PREFIX : <http://valuenet/ontop/>

select ?t1_killed ?t1_injured WHERE {
  SERVICE <http://host.docker.internal:3030/battle_death__ship/sparql> {
    SELECT DISTINCT ?t2 ?t2_tonnage WHERE {
      ?t2 a :ship .
      ?t2 :ship\#tonnage ?t2_tonnage
      FILTER(?t2_tonnage = 't')
    }
  }
  SERVICE <http://host.docker.internal:3030/battle_death__death/sparql> {
    ?t1 a :death .
      ?t1 :death\#ref-caused_by_ship_id ?t2 .
      ?t1 :death\#killed ?t1_killed .
      ?t1 :death\#injured ?t1_injured
  }
}

PREFIX : <http://valuenet/ontop/>

select distinct ?t1_id ?t1_name WHERE {
  SERVICE <http://host.docker.internal:3030/battle_death__ship/sparql> {
    SELECT DISTINCT ?t2 ?t2_ship_type WHERE {
      ?t2 a :ship .
      ?t2 :ship\#ship_type ?t2_ship_type
      FILTER(?t2_ship_type = 'Brig')
    }
  }
  SERVICE <http://host.docker.internal:3030/battle_death__battle/sparql> {
    ?t1 a :battle .
      ?t2 :ship\#ref-lost_in_battle ?t1 .
      ?t1 :battle\#id ?t1_id .
      ?t1 :battle\#name ?t1_name
  }
}

PREFIX : <http://valuenet/ontop/>

select ?t1_id ?t1_name WHERE {
  {
    SELECT ?t1 ?t1_id ?t1_name ?t2 ?t3 ?t3_killed WHERE {
  SERVICE <http://host.docker.internal:3030/battle_death__ship/sparql> {
    SELECT DISTINCT ?t2 WHERE {
      ?t2 a :ship
    }
  }
  SERVICE <http://host.docker.internal:3030/battle_death__battle/sparql> {
    ?t1 a :battle .
      ?t2 :ship\#ref-lost_in_battle ?t1 .
      ?t1 :battle\#id ?t1_id .
      ?t1 :battle\#name ?t1_name .
      ?t1 :battle\#id ?t1_id .
      ?t1 :battle\#id ?t1_id .
      ?t1 :battle\#name ?t1_name .
      ?t1 :battle\#id ?t1_id
  }
  SERVICE <http://host.docker.internal:3030/battle_death__death/sparql> {
    ?t3 :death\#killed ?t3_killed .
      ?t3 a :death .
      ?t3 :death\#ref-caused_by_ship_id ?t2 .
      ?t3 :death\#killed ?t3_killed
  }
    }
  }
}
group by ?t1_id ?t1_name   having(sum( ?t3_killed)  > 10)

