PREFIX : <http://valuenet/ontop/>

select distinct ?t1_name ?t1_date WHERE {
  SERVICE <http://host.docker.internal:3030/battle_death__ship/sparql> {
    SELECT DISTINCT ?t2 ?t2_name ?t4 ?t4_name WHERE {
      ?t2 a :ship .
      ?t2 :ship\#name ?t2_name .
      ?t4 a :ship .
      ?t4 :ship\#name ?t4_name
      FILTER(?t2_name = 'Lettice')
      FILTER(?t4_name = 'HMS Atalanta')
    }
  }
  SERVICE <http://host.docker.internal:3030/battle_death__battle/sparql> {
    ?t1 a :battle .
      ?t2 :ship\#ref-lost_in_battle ?t1 .
      ?t1 :battle\#name ?t1_name .
      ?t1 :battle\#date ?t1_date .
      ?t3 a :battle .
      ?t4 :ship\#ref-lost_in_battle ?t3 .
      ?t3 :battle\#name ?t3_name .
      ?t3 :battle\#date ?t3_date
      FILTER (?t1_name in (?t3_name))
      FILTER (?t1_date in (?t3_date))
  }
}

